import React from "react";

function Video( {path,classes} ) {
  let cls = "sm:w-full md:w-1/2 "
  if(classes != ""){
    cls += classes
  }
  return (
    <div className={cls}>
      <video
        src={path}
        loop
        autoPlay
        muted
        className="md:h-screen w-full "
      ></video>
    </div>
  );
}

export default Video;
